// `page` and `expect` are the only globals.
// The app is an answer-review queue. Approve is disabled while it loads.

await page.getByTestId('approve').click();

await expect(page.getByTestId('status')).toHaveText('approved 1');

// textContent() reads once. It does not retry.
await page.waitForTimeout(200);

const answer = await page.getByTestId('answer').textContent();

if (!answer.includes('anomaly scan')) {
    throw new Error('Answer had not loaded yet: ' + answer);
}
